<script>
(function(){
 const root=document.querySelector('.oys-ia'); if(!root)return;
 root.querySelector('#ia-print-button').addEventListener('click',()=>window.print());
 root.querySelectorAll('.ia-unassign').forEach(a=>a.addEventListener('click',e=>{if(!confirm('Unassign this course from the instructor?'))e.preventDefault()}));
 const search=root.querySelector('#ia-search'),rows=Array.from(root.querySelectorAll('.ia-item')),empty=root.querySelector('#ia-no-match');
 search.addEventListener('input',()=>{const q=search.value.toLowerCase().trim();let found=0;rows.forEach(row=>{const show=row.textContent.toLowerCase().includes(q);row.style.display=show?'':'none';if(show)found++});empty.style.display=rows.length&&!found?'':'none'});
 const dept=root.querySelector('#department'),programme=root.querySelector('#programme'),level=root.querySelector('#stdLevel'),semester=root.querySelector('#semesterDropdown'),course=root.querySelector('#courseDropdown'),status=root.querySelector('#ia-ajax-status');
 const csrf=root.querySelector('input[name="_token"]').value;
 const urls={programmes:@json(route('get-programmes')),courses:@json(route('get-courses'))};
 let progController=null,courseController=null;
 const reset=(select,label)=>{select.replaceChildren(new Option(label,''));};
 const populate=(select,items,valueKey,textFn)=>{reset(select,'Select an option');(Array.isArray(items)?items:Object.values(items||{})).forEach(item=>{const text=textFn(item);select.add(new Option(text,String(item[valueKey]??'')))});};
 async function post(url,data,signal){const res=await fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','Accept':'application/json','X-Requested-With':'XMLHttpRequest','X-CSRF-TOKEN':csrf},body:JSON.stringify(data),signal});if(!res.ok)throw Error('Request failed ('+res.status+')');return res.json()}
 async function loadProgrammes(){if(progController)progController.abort();progController=new AbortController();reset(programme,'Loading programmes...');reset(course,'Select the fields above');status.textContent='';if(!dept.value){reset(programme,'Select department first');return}try{const data=await post(urls.programmes,{department:dept.value},progController.signal);populate(programme,data,'dept_name',p=>p.dept_name);status.textContent=''}catch(e){if(e.name!=='AbortError'){reset(programme,'Unable to load programmes');status.textContent='Unable to load programmes. Please retry.'}}}
 async function loadCourses(){if(courseController)courseController.abort();courseController=new AbortController();reset(course,'Select the fields above');status.textContent='';if(!dept.value||!programme.value||!level.value||!semester.value)return;reset(course,'Loading courses...');try{const data=await post(urls.courses,{department:dept.value,programme:programme.value,stdLevel:level.value,semester:semester.value},courseController.signal);populate(course,data,'id',c=>(c.course_title||'')+' - '+(c.course_code||''));status.textContent=course.options.length<=1?'No courses found for these criteria.':''}catch(e){if(e.name!=='AbortError'){reset(course,'Unable to load courses');status.textContent='Unable to load courses. Please retry.'}}}
 dept.addEventListener('change',loadProgrammes);programme.addEventListener('change',loadCourses);level.addEventListener('change',loadCourses);semester.addEventListener('change',loadCourses);
})();
</script>
